import org.apache.jmeter.config.Arguments;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

Arguments args = sampler.getArguments(); 
String body = args.getArgument(0).getValue();

String timestamp = "1678967946";
String endpoint = "/transactions/authorizations";
String signPrefix = "hmac-sha256 ";
String secret = "${api-secret}";
String algo = "HmacSHA256";
String contentBuilder = Optional.ofNullable(timestamp).orElse("") +
                        Optional.ofNullable(endpoint).orElse("") +
                        body;


try{
    String hashValue = "test";
    Mac hmacSha256 = Mac.getInstance(algo);
    byte[] secretBytes = Base64.getDecoder().decode(secret);
    SecretKeySpec secretKey = new SecretKeySpec(secretBytes, algo);
    hmacSha256.init(secretKey);
    byte[] bytes = hmacSha256.doFinal(contentBuilder.getBytes());
    hashValue = signPrefix + Base64.getEncoder().encodeToString(bytes);
    // log.info("hash value:{}", hashValue);
    vars.put("signature", hashValue);
}catch(Exception e){
    e.printStackTrace();
}

