    SimpleDateFormat formatCurrent = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    String outputDate = formatCurrent.format(date);
    SimpleDateFormat formatUtc = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    formatUtc.setTimeZone(TimeZone.getTimeZone("GMT+14"));
    String outputDateUtc = formatUtc.format(date);

    log.info("outputDate is: " + outputDate);
    vars.put("MS.ENV.null."+"systemTimestamp", outputDate);
    vars.put("systemTimestamp", outputDate);
    log.info("outputDateUtc is: " + outputDateUtc);
    vars.put("MS.ENV.null."+"systemTimestampUtc", outputDateUtc);
    vars.put("systemTimestampUtc", outputDateUtc);
}

