import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.*;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;
import java.util.*;
import java.text.*;
import java.util.Date;
import org.json.JSONObject;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TimeZone;

// 创建http请求
HttpGet request = new HttpGet("${getCurrentSystemTimeInterfaceHost}");
// 创建Httpclient对象
CloseableHttpClient httpclient = HttpClients.createDefault();
//response 对象
CloseableHttpResponse response = httpclient.execute(request);
// 判断返回状态是否为200
if (response.getStatusLine().getStatusCode() == 200) {
    String result = EntityUtils.toString(response.getEntity(), "UTF-8");
    // 获取data.currentSystemTime
    JSONObject jsonObject = new JSONObject(result);
    String currentSystemTime = jsonObject.get("data").getString("currentSystemTime");
    log.info("currentSystemTime is: " + currentSystemTime);
    // 将string转换成date
    SimpleDateFormat inputFormat = new SimpleDateFormat("yyyyMMdd HH:mm:ss.SSS");
    Date date = inputFormat.parse(currentSystemTime);

    // 转换成 系统当前时间 & UTC时间
    SimpleDateFormat formatCurrent = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
    String outputDate = formatCurrent.format(date);
    SimpleDateFormat formatUtc = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
    formatUtc.setTimeZone(TimeZone.getTimeZone("GMT+14"));
    String outputDateUtc = formatUtc.format(date);

    log.info("outputDate is: " + outputDate);
    vars.put(${__metersphere_env_id}+"systemTimestamp", outputDate);
    vars.put("systemTimestamp", outputDate);
    log.info("outputDateUtc is: " + outputDateUtc);
    vars.put(${__metersphere_env_id}+"systemTimestampUtc", outputDateUtc);
    vars.put("systemTimestampUtc", outputDateUtc);
}

